namespace Encspect.Formats.Dts;

// The background articles the DTS nodes point to, by the IDs the host's topic library serves.
internal static class Topics
{
    public const string CoreFrames = "dts-core-frames";
    public const string CoreCodingHeader = "dts-audio-coding-header";
    public const string CoreBitstreamForms = "dts-bitstream-forms";
    public const string CoreExtensions = "dts-core-extensions";
    public const string ExtensionSubstream = "dts-extension-substream";
    public const string DtsChannelArrangements = "dts-channel-arrangements";
    public const string Crc = "crc";
    public const string BitrateModes = "bitrate-modes";
    public const string DialogueNormalization = "dialogue-normalization";
    public const string DynamicRange = "dialogue-normalization";
    public const string Lfe = "channel-layouts";
    public const string FilterBank = "dts-core-frames";
    public const string EncoderDetection = "encoder-detection";
    public const string Lossless = "dts-lossless-extension";
}

// What each DTS node is, in the words the report shows next to it, citing ETSI TS 102 114 V1.6.1 by its clauses and tables
// (and FFmpeg's and libdca's sources where the specification does not describe a form or a code). Constants only: frames are
// built by the hundred thousand, so a description is one of these and never allocated.
internal static class Explain
{
    public const string Stream = "DTS data: frames one after another, each a core frame that may carry core extensions and be followed by extension substreams (ETSI TS 102 114 5.2, 7.2).";
    public const string Frame = "One unit of a DTS stream: a core frame and the extension substreams that follow it, or an extension substream alone (7.2, 7.5.1).";
    public const string Gap = "Bytes between frames that are no frame: data before the first frame, after the last, or where sync was lost.";

    public const string CoreSubstream = "The core substream: a DTS Coherent Acoustics frame of up to 5.1 channels with its header, subframes and optional core extension (5.2).";
    public const string SubstreamCore = "A core component inside an extension substream: a core frame whose sync word is remapped to 0x02B09261 (7.4.1, Table 7-1).";
    public const string Synchronization = "The sync word that starts every core frame, and the form the stream is written in (5.3).";
    public const string SyncWord = "SYNC: the 32-bit sync word 0x7FFE8001 of a core frame (5.4.2). The 16-bit little endian and the 14-bit forms write it as 0xFE7F0180, 0x1FFFE800 and 0xFF1F00E8 (FFmpeg's dca_syncwords.h).";
    public const string SubstreamCoreSyncWord = "SYNC: the sync word of a core component inside an extension substream, 0x02B09261, which stands in for 0x7FFE8001 (7.4.1, Table 7-1).";
    public const string WordSize = "How many bits of each 16-bit word of the file the stream uses: 16 in the 16-bit forms, 14 in the forms that CDs and S/PDIF carry (FFmpeg's dca.c, libdca's parse.c).";
    public const string IsBigEndian = "Whether the words of the file are big endian, the byte order the specification's bit numbering follows, or little endian, with each pair of bytes swapped (FFmpeg's dca.c, libdca's parse.c).";

    public const string FrameHeader = "The bit stream header: the frame's construction, the encoder's configuration and the optional features it uses (5.4.2, Table 5-1).";
    public const string Ftype = "FTYPE: 1 for a normal frame, 0 for a termination frame that ends the audio where a video frame ends (5.4.2, Table 5-2).";
    public const string Short = "SHORT: the deficit sample count, how many core samples a termination frame falls short of a block of 32; 31 for a normal frame (5.4.2, Table 5-3).";
    public const string Cpf = "CPF: whether CRC words follow the headers and subframes; the specification says it should always be 0, and a decoder tests the flag (5.4.2).";
    public const string Nblks = "NBLKS + 1: the number of blocks of 32 PCM samples per channel in the frame, which makes 32 times as many samples; normal frames hold 256, 512, 1,024, 2,048 or 4,096 (5.4.2).";
    public const string Fsize = "FSIZE + 1: the frame's size in bytes of the bit-packed stream, with the extension data it holds; 96 to 16,384 (5.4.2). A 14-bit form takes 8/7 as many bytes in the file.";
    public const string Amode = "AMODE: the audio channel arrangement, how many channels the frame codes and where they play; the values from 16 are user defined (5.4.2, Table 5-4).";
    public const string Sfreq = "SFREQ: the core sampling frequency, 8 to 48 kHz; the codes the table leaves out are invalid (5.4.2, Table 5-5).";
    public const string Rate = "RATE: the targeted bit rate, which may be at least the actual one; 29 is open mode, for rates the table does not list (5.4.2, Table 5-7). FFmpeg and libdca list 896 kbit/s for code 16, where the table says 960.";
    public const string FixedBit = "FixedBit: a reserved bit that is always 0 (5.4.2).";
    public const string Dynf = "DYNF: whether each subframe starts its side information with a dynamic range coefficient (5.4.2, Table 5-8).";
    public const string Timef = "TIMEF: whether a time stamp follows the audio data at the end of the core frame (5.4.2, Table 5-9).";
    public const string Auxf = "AUXF: whether auxiliary data bytes follow the audio data (5.4.2, Table 5-10).";
    public const string Hdcd = "HDCD: whether the source was mastered in HDCD format (5.4.2).";
    public const string ExtAudioId = "EXT_AUDIO_ID: which extension the extended audio holds, when EXT_AUDIO is set: channel extension (XCh), frequency extension (X96) or channel extension beyond 5.1 (XXCH) (5.4.2, Table 5-11).";
    public const string ExtAudio = "EXT_AUDIO: whether extended audio data follow the core audio data in the frame (5.4.2, Table 5-12).";
    public const string Aspf = "ASPF: whether the DSYNC word 0xFFFF follows each subsubframe or only each subframe (5.4.2, Table 5-13).";
    public const string Lff = "LFF: whether the frame codes an LFE channel and the factor by which its samples are interpolated (5.4.2, Table 5-14).";
    public const string Hflag = "HFLAG: whether the ADPCM predictor history of the frame before is used; a frame that starts without it can serve as an entry point (5.4.2).";
    public const string Hcrc = "HCRC: the header's CRC, present when CPF is 1; the specification says the value is read and the test is not applied (5.4.2).";
    public const string Filts = "FILTS: whether the 32-band interpolation filter reconstructs perfectly or not (5.4.2, Table 5-15).";
    public const string Vernum = "VERNUM: the revision of the encoder software, 7 for the one the specification describes; it also says whether DIALNORM is present (5.4.2, Table 5-16).";
    public const string Chist = "CHIST: the copy history of the audio, whose definition the specification leaves out on purpose (5.4.2).";
    public const string Pcmr = "PCMR: the resolution of the source PCM samples, 16, 20 or 24 bits, and with it the ES flag (5.4.2, Table 5-17).";
    public const string Es = "ES: whether the surround channels of the source were mastered in the DTS-ES format (5.4.2, Table 5-17).";
    public const string Sumf = "SUMF: whether the front left and right channels were sum/difference encoded before coding and need decoding afterward (5.4.2, Table 5-18).";
    public const string Sums = "SUMS: whether the surround left and right channels were sum/difference encoded before coding (5.4.2, Table 5-19).";
    public const string Dialnorm = "DNG: the dialog normalization gain in dB, from DIALNORM and VERNUM 6 or 7, which scales the decoder's output samples (5.4.2, Table 5-20).";
    public const string Unspec = "UNSPEC: a field a decoder reads and ignores for every VERNUM but 6 and 7, where it holds DIALNORM (5.4.2).";

    public const string AudioHeader = "The primary audio coding header: how the subframes are packed, per channel, the number of subbands, the codebooks of the side information and the quantizers (5.4.3, Table 5-21).";
    public const string Subfs = "SUBFS + 1: the number of subframes in the frame, each decodable without reference to the others (5.4.3).";
    public const string Pchs = "PCHS + 1: the number of primary audio channels in the frame, which is at most 5; more channels are extension channels (5.4.3).";
    public const string Subs = "SUBS + 2: the number of active subbands of a channel; the samples above are zero unless joint intensity coding fills them (5.4.3).";
    public const string Vqsub = "VQSUB + 1: the first subband of a channel whose samples are vector quantized, one 10-bit address per subband in the subframe (5.4.3).";
    public const string Joinx = "JOINX: whether a channel copies the subbands above its active ones from an earlier channel by joint intensity coding, and which channel is the source (5.4.3, Table 5-22).";
    public const string Thuff = "THUFF: the Huffman codebook of the transient mode data (5.4.3, Table 5-23).";
    public const string Shuff = "SHUFF: the codebook of a channel's scale factors, a Huffman code over differences or linear, and the 6-bit or 7-bit square root table they index (5.4.3, Table 5-24).";
    public const string Bhuff = "BHUFF: the codebook of the bit allocation indexes ABITS, a Huffman code or a linear 4 or 5 bits (5.4.3, Table 5-25).";
    public const string Sel = "SEL: for the quantizer ABITS, the codebook of its quantization indexes: a Huffman code, a block code or none (5.4.3, Table 5-26).";
    public const string Adj = "ADJ: the adjustment, 1.0000, 1.1250, 1.2500 or 1.4375, that scales a channel's scale factors where a Huffman code is used for the quantizer (5.4.3, Table 5-27).";
    public const string Ahcrc = "AHCRC: the audio header's CRC, present when CPF is 1; the specification says the value is read and the test is not applied (5.4.3).";
    public const string CoreAudioData = "The subframes and the optional information of the core frame: side information, audio data and DSYNC words, then a time stamp and auxiliary data. Not read; the extensions are found from the end of the frame (5.5 to 5.8).";

    public const string Xch = "The channel extension XCh: one extra center surround channel, which makes 6.1, coded like the core's channels and placed at the end of the frame (6.4.1).";
    public const string XchSync = "XChSYNC: 0x5A5A5A5A on a 32-bit boundary, the sync word of the XCh extension (6.4.2, Table 6-17).";
    public const string XchFsize = "XChFSIZE + 1: the distance in bytes from this sync word to the end of the frame, which tells a true sync word from a pattern in the audio data (6.4.2).";
    public const string XchAmode = "AMODE: the extension's channel arrangement, set to represent the number of extension channels (6.4.2).";
    public const string XchAudioHeader = "The audio header of the extension channels, laid out like the primary audio coding header without SUBFS (6.4.3, Table 6-18).";
    public const string XchPchs = "PCHS + 1: the number of extension channels (6.4.3).";
    public const string XchData = "The side information and audio data of the extension channels. Not read (6.4.4).";
    public const string X96 = "The frequency extension X96: the high-frequency components that a sampling frequency of 88.2 or 96 kHz adds to the core's 44.1 or 48 kHz, in 64 subbands (6.2).";
    public const string X96Sync = "SYNC96: 0x1D95F262 on a 32-bit boundary, the sync word of the X96 extension (6.2.4.2, Table 6-1).";
    public const string X96Fsize = "FSIZE96 + 1: the size in bytes of the extension data, which is the distance from this sync word to the end of the frame (6.2.4.2).";
    public const string X96Revno = "REVNO: the revision of the extension's algorithm; 1 is current, 2 to 7 compatible, 8 and above incompatible with the original specification (6.2.4.2, Table 6-2).";
