    public const string X96HighRes = "HIGHRES-FLAG96K: whether bit allocation indexes go to 15 instead of 7 (6.2.4.4, Table 6-5).";
    public const string X96Sbs = "nSBS96: the first extension subband that is coded; those below are zero (6.2.4.4).";
